text:
This makes the test image 100x100 pixels.   When this was originally created,
it was determined that default test image be 100x100.   Then a few months later
a case cropped up where it would have been much more efficient to 'downsize'
the test image to be smaller, hence conceived of way to default to a smaller size.
Shortening of testing picture was done by request of user on GitHub - Credit Due

So, instead of using this image decorator to increase the size of the image,
I'm using it to shrink the size for quicker tests.
'''

https://github.com/reinbach/django-image-fields/commit/a45f1d9b4455bf3a9e3f5024e2af0976ab3d0a6c
'''

from django.core.files.uploadedfile import InMemoryUploadedFile


class Image:
    def __init__(self):
        self.dimensions = (100, 100)
        self.color = 'blue'
        self.name = 'image.jpg'

    @property
    def django_file(self):
        # Create a new Django file-like object to be used in models as ImageField using
        # InMemoryUploadedFile.  If you look at the source in Django, a
        # SimpleUploadedFile is essentially instantiated similarly to what is shown here
        return InMemoryUploadedFile(self.image_file, None, self.name, 'image/jpeg',
                                    self.image_file.len, None)

    @property
    def image_file(self):
        # Create a file-like object to write thumb data (thumb data previously created
        # using PIL, and stored in variable 'thumb')
        image_io = StringIO.StringIO()
        self.pil_image.save(image_io, format='JPEG')
        image_io.seek(0)
        return image_io

    @property
    def pil_image(self):
        return PIL.Image.new('RGB', self.dimensions, self.color)


@pytest.fixture()
def small_image():
    img = Image()
    img.dimensions= (25, 25)
    return img

