    hashed2 = self.agileclu.e_pw_hash('s3cr3t')
    statement1 = hashed1 == hashed2
    statement2 = hashed1 != 's3cr3t'
    self.assertTrue(statement1, 'Hashed values differ.')
    self.assertTrue(statement2, 'Hashed value and plaintext are identical.')
  def test_e_pw_dehash(self):
    hashed = self.agileclu.e_pw_hash('s3cr3t')
    plaintext = self.agileclu.e_pw_dehash(hashed)
    self.assertEqual('s3cr3t', plaintext)

